#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAXN = 1e6 + 10;
int n, a[MAXN];
ll x[MAXN];
int main() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    ll ans = 0;
    // 枚举每一位 k
    for (int k = 0; k <= 30; k++) {
        ll bit = 1LL << k;
        ll mask = bit << 1; // 2^(k+1)
        for (int i = 0; i < n; i++) {
            x[i] = a[i] % mask;
        }
        sort(x, x + n);
        ll cnt = 0;
        ll L1 = bit, R1 = mask;
        ll L2 = 3 * bit, R2 = mask * 2;
        for (int i = 0; i < n; i++) {
            ll v = x[i];
            // [L1 - v, R1 - v)
            cnt += upper_bound(x, x + n, R1 - 1 - v) - lower_bound(x, x + n, L1 - v);
            // [L2 - v, R2 - v)
            cnt += upper_bound(x, x + n, R2 - 1 - v) - lower_bound(x, x + n, L2 - v);
        }
        if (cnt % 2 == 1) {
            ans |= bit;
        }
    }
    cout << ans << endl;
    return 0;
}
```

